let legSequence=0;
function builderPage(){
 $('app').innerHTML=heading('Strategy studio','Backtester','Build a strategy from minute candles. Times are in IST.',importButton+' <button onclick="strategyLibrary()">Saved strategies</button>')+'<form id="strategy" class="panel"><div class="row">'+select('Strategy','strategyMode',['Equity','Options','Basket','Future'])+'<button type="button" id="addLeg">＋ Add leg</button></div><div class="fields">'+select('Dates','bp',presetNames)+input('From','bf',presetStart(end,'7D'),'date')+input('Through','bt',end,'date')+input('Entry when · time of day','et','09:30','time')+input('Exit when · time of day','xt','15:15','time')+'</div><div id="legs"></div><h3>Algo trade exit</h3><div class="fields">'+select('Trade type','holding',['Intraday','Delivery'])+input('Max entries per day · all legs','maxEntries',4,'number','min="1"')+input('Slippage · bps per fill','slip',0,'number','min="0" step="any"')+'</div><div class="row"><button type="button" onclick="chargesPanel()">Charges &amp; taxes</button><span id="feeSummary"></span><button class="primary">Run backtest</button></div><p role="status" id="runMessage"></p><details><summary>Execution rules</summary>Each basket opens once per eligible day, only when every leg qualifies. The entry limit counts legs. Stops take priority inside an ambiguous candle. Gaps fill at the open. Incomplete candle windows skip the session. Delivery exits on the next observed session. Weekly windows use Monday through Sunday. Monthly uses the latest imported matching expiry in the entry month. Check contract coverage before running.</details></form><div id="results"></div>';
 const legs=$('legs'),sources=testSources();
 function add(kind){
 const n=++legSequence,el=document.createElement('section');el.className='legrow';
 const field=(label,key,value,type='number',attrs='min="0" step="any"')=>input(label,key+n,value,type,attrs);
 const choice=(label,key,items)=>select(label,key+n,items);
 el.innerHTML='<div class="row"><h3></h3><button type="button" aria-label="Remove leg">×</button></div><div class="fields">'+choice('Leg type','kind',['Equity','Options','Future'])+'<label>Search<input required type="search" id="symbol'+n+'" list="names'+n+'" autocomplete="off" placeholder="Name or symbol"><datalist id="names'+n+'"></datalist></label>'+choice('Direction','side',['Buy','Sell'])+field('Lots / quantity','lots',1,'number','min="1" step="1"')+field('Units per lot','units',1,'number','min="1" step="1"')+'</div><div class="fields opt">'+choice('Expiry','term',['Exact contract','This week','Next week','Monthly'])+choice('Contract side','cp',['CE','PE'])+field('Days before expiry','days','','number','min="0" step="1" placeholder="Any"')+choice('Entry condition','rule',['Time only','Strike price','Premium above','Premium below','Premium near','Spot above','Future above','Delta above','Delta below','Indicator above'])+field('Condition value','value',0)+field('Near tolerance ₹','tol',1)+'</div><div class="fields">'+riskField('Stop loss','sl'+n,'su'+n,0.6)+riskField('Take profit','tp'+n,'tu'+n,1)+field('Trail · instrument moves X pts','tx',0)+field('Move stop by Y pts','ty',0)+'</div>';
 legs.append(el);let get=k=>$(k+n);get('kind').value=kind;
 get('days').required=false;for(let k of ['cp','side','su','tu'])segmentedIds.add(k+n);
 function available(){return sources.filter(x=>get('kind').value==='Options'?x.data?.kind==='Option contract'&&(x.data.optionType===get('cp').value||x.s.endsWith(get('cp').value)):get('kind').value==='Future'?x.data?.kind==='Future':!['Option contract','Future'].includes(x.data?.kind))}
 function update(){el.querySelector('.opt').hidden=get('kind').value!=='Options';let a=available();get('names').innerHTML=a.map(x=>'<option value="'+esc(x.title)+'"></option>').join('');get('symbol').value=(a.find(x=>x.s==='SENSEX')||a[0])?.title||''}
 get('kind').onchange=get('cp').onchange=update;update();
 el.config=()=>{let q=get('symbol').value.trim().toUpperCase(),src=available().find(x=>x.title.toUpperCase()===q)||available().find(x=>x.s===q);if(!src)throw Error('Select an available search result. Options require historical minute prices for the exact contract.');
 let opt=get('kind').value==='Options';let p={id:src.id,s:src.s,source:src.title,mode:get('kind').value,side:get('side').value,qty:+get('lots').value*+get('units').value,stop:+get('sl').value,target:+get('tp').value,stopUnit:get('su').value,targetUnit:get('tu').value,trailX:+get('tx').value,trailY:+get('ty').value,rule:opt?get('rule').value:'Time only',ruleValue:+get('value').value,tolerance:+get('tol').value,strike:src.data?.strike,expiry:opt?src.data?.expiry:'',dte:opt?get('days').value:'',term:opt?get('term').value:'',fees:[...feeSchedule]};
 if((p.trailX||p.trailY)&&!(p.trailX&&p.trailY&&p.stop))throw Error('Trailing requires a stop and positive X and Y values.');
 if(opt&&!p.expiry)throw Error('Import the contract with an expiry date.');
 p.latestExpiry=opt?available().filter(x=>x.data.expiry?.slice(0,7)===p.expiry.slice(0,7)&&x.s.match(/^[A-Z &-]+/)?.[0]===src.s.match(/^[A-Z &-]+/)?.[0]).map(x=>x.data.expiry).sort().at(-1):'';
 return {p,rows:src.data?.rows||(candleCache[src.id]??=demoBars(src.s))}};
 el.querySelector('button').onclick=()=>{el.remove();if(!legs.children.length)add('Equity');renumber()};renumber();
 }
 function renumber(){[...legs.children].forEach((el,i)=>el.querySelector('h3').textContent='Leg '+(i+1))}
 $('strategyMode').onchange=()=>{if($('strategyMode').value==='Basket')return;legs.replaceChildren();add($('strategyMode').value)};
 $('addLeg').onclick=()=>{$('strategyMode').value='Basket';$('strategyMode').dispatchEvent(new Event('change'));add('Equity')};
 $('bp').onchange=()=>{let custom=$('bp').value==='Custom';$('bf').disabled=$('bt').disabled=!custom;if(!custom)$('bf').value=presetStart($('bt').value,$('bp').value)};$('bp').onchange();add('Equity');
 $('strategy').onsubmit=e=>{e.preventDefault();try{const configs=[...legs.children].map(l=>l.config());if(configs.length>+$('maxEntries').value)throw Error('Increase max entries per day to cover every basket leg.');
 const common={from:$('bf').value,to:$('bt').value,entry:toMin($('et').value),exit:toMin($('xt').value),holding:$('holding').value==='Delivery'?'Positional':'Intraday',slip:+$('slip').value};
 const runs=configs.map(({p,rows})=>simulate(rows,{...p,...common}));let shared=new Set(runs[0].trades.map(t=>t.entryDay));for(let r of runs){let dates=new Set(r.trades.map(t=>t.entryDay));shared=new Set([...shared].filter(d=>dates.has(d)))}
 let trades=runs.flatMap((r,i)=>r.trades.filter(t=>shared.has(t.entryDay)).map(t=>({...t,s:r.p.s,side:r.p.side,qty:r.p.qty,stop:r.p.stop,stopUnit:r.p.stopUnit,leg:i+1}))).sort((a,b)=>(a.d+a.exit).localeCompare(b.d+b.exit)||a.leg-b.leg);
 let net=0,peak=0,dd=0,value=0;for(let t of trades){net+=t.net;peak=Math.max(peak,net);t.cum=net;t.dd=net-peak;dd=Math.min(dd,t.dd);value+=t.qty*t.ep;t.tip=t.d+' '+t.exit+' · '+t.s+' · Net ₹'+fmt(t.net)+' · Cumulative ₹'+fmt(net)}
 let p={...runs[0].p,legs:runs.map(r=>r.p),s:configs.map(c=>c.p.s).join(' + '),id:configs.map(c=>c.p.id).join('|'),source:configs.map(c=>c.p.source).join(' / ')};
 lastRun={p,trades,net,dd,ret:value?100*net/value:0,win:trades.length?100*trades.filter(t=>t.net>0).length/trades.length:0,skipped:[...new Set(runs.flatMap(r=>r.skipped))]};lastMonth='';$('runMessage').textContent=shared.size+' eligible basket sessions';showResults();
 }catch(err){$('results').replaceChildren();$('runMessage').textContent=err.message}};
}
segmentedIds.add('strategyMode');
backtester=builderPage;
